#!/usr/bin/env python3
"""Repro: Vulkan operator bug `floor_divide` on ASUS a12201 (Vulkan).
Single-op graph fed the op's EXACT runtime inputs (baked from corpus job w0:117 out[3]),
lowered to Vulkan, run on the connected device. Prints eager (CPU) vs device.
Needs a connected Vulkan worker (broker 127.0.0.1:15554).
"""
import os, sys, time, warnings, logging
os.environ.setdefault("CUDA_VISIBLE_DEVICES", "")
warnings.filterwarnings("ignore"); logging.disable(logging.WARNING)
sys.path.insert(0, "/data/jwen929")
import torch, zmq
from mobile.gen.export import build_job
from mobile.executor import protocol as P, compare as cmp

SRC = 'import torch\ndef _first(r):\n    if isinstance(r, torch.Tensor): return r\n    if isinstance(r, (tuple, list)):\n        for x in r:\n            if isinstance(x, torch.Tensor): return x\n    return r\nB0 = torch.tensor([4, 3, 2, 1], dtype=torch.uint8).reshape([4])\nB1 = torch.tensor([0.4118565320968628, 0.027458935976028442, -0.005105555057525635, 0.01195669174194336, -0.0317508801817894, -0.17265349626541138, -0.1424037218093872, 0.03961688280105591, -0.13910818099975586, -0.0038061365485191345, 0.014973640441894531, -0.010898925364017487, -0.14437603950500488, -0.0023347437381744385, -0.14665867388248444, -0.005543403327465057, -0.003497280180454254, 0.07148134708404541, 0.08221055567264557, -0.3710596561431885, 0.2450844645500183, -0.3540782928466797, -0.3074066638946533, -0.02901172637939453, -0.0030018091201782227, -0.07480964064598083, -0.06512914597988129, 0.19314569234848022, 0.659517765045166, 0.12577533721923828, -0.28135228157043457, 0.12365740537643433, -0.6721707582473755, -0.21303915977478027, -0.10987979173660278, -0.16280025243759155, -0.9159563779830933, -0.6417059898376465, -0.02093525230884552, 0.14543896913528442, 0.20443010330200195, -0.020036697387695312, -0.8461545705795288, -0.39552751183509827, 0.15392327308654785, -0.21901565790176392, -0.4204818904399872, 0.09994196891784668, 0.07933878898620605, 0.10344234108924866, -0.0184323787689209, -0.3968043327331543, 0.8634244203567505, 0.11114299297332764, -0.10156655311584473, -0.15546712279319763, 0.4960312843322754, 0.24150949716567993, 0.0004099849611520767, 0.12391549348831177, -0.17803049087524414, -0.020016908645629883, 0.03269825130701065, -0.18166160583496094, 0.4706188440322876, 0.013729467988014221, -0.0025527775287628174, 0.00597834587097168, -0.06934256851673126, -0.08632674813270569, -0.2854422330856323, 0.019808441400527954, -0.06955409049987793, -0.06083854287862778, 0.007486820220947266, -0.0299726203083992, -0.07218801975250244, -0.11240819096565247, -0.15589313209056854, -0.06175827234983444, -0.009280584752559662, 0.035740673542022705, 0.12827752530574799, -0.4226357936859131, 0.4150281548500061, -0.17703914642333984, -0.15370333194732666, -0.15943527221679688, -0.0015009045600891113, -0.03740482032299042, -0.0817343145608902, 0.2772582769393921, 1.0, 0.06288766860961914, -0.14067614078521729, 0.06182870268821716, -0.781447172164917, -0.10651957988739014, -0.1721554398536682, -0.2358858585357666, -0.9439709186553955, -0.32085299491882324, -0.08819590508937836, 0.3818129897117615, 0.10221505165100098, -0.010018348693847656, -0.8974363803863525, -0.43731650710105896, 0.07696163654327393, -0.23278647661209106, -0.4522891342639923, 0.04997098445892334, 0.03966939449310303, 0.1379283368587494, -0.00921618938446045, -0.19840216636657715, 1.0, 0.05557149648666382, -0.4010443687438965, -0.07773356139659882, 0.2480156421661377, 0.296603798866272, 0.001615140587091446, 0.166184663772583, -0.08901524543762207, -0.010008454322814941, 0.016349125653505325, -0.09083080291748047], dtype=torch.float32).reshape([2, 4, 2, 2, 4])\nLEAVES = [B0, B1]\ndef g(B0, B1):\n    T = _first(_first(torch.ops.aten.floor_divide.default(B0, B1)))\n    return (T,)\n'

job = build_job(SRC, "vulkan", False)
assert job.status == "READY", f"lower failed: {job.status}"
ctx = zmq.Context.instance(); D = ctx.socket(zmq.DEALER)
D.setsockopt(zmq.HEARTBEAT_IVL, 5000); D.connect("tcp://127.0.0.1:15554")
P_ = zmq.Poller(); P_.register(D, zmq.POLLIN)
fr = P.encode_pushjob("repro::floor_divide", job.pte, job.inputs, job.eager, desc="repro", user_pos=job.user_pos)
D.send_multipart(P.job_frames_from_pushjob(fr))
t0 = time.monotonic()
while time.monotonic() - t0 < 60:
    if dict(P_.poll(1000)).get(D):
        _, st, det, raw = P.decode_result(D.recv_multipart())
        if st != "RAN":
            print("device status:", st, det[:120]); break
        et = cmp.select(raw, job.user_pos)
        if len(et) > len(job.eager): et = et[len(et)-len(job.eager):]
        e, d = job.eager[0], et[0]
        status, detail = cmp._cmp(e, d, 0)
        print("op `floor_divide`  ->", status, detail)
        print("  eager :", e.float().flatten()[:8].tolist())
        print("  device:", d.float().flatten()[:8].tolist())
        break
